{"cards": [{"node_code": "N_00fa0136bc4a5091", "definition": "研究皮肤及附属器（毛发、指甲、皮脂腺等）的良性与恶性肿瘤，以及非肿瘤性附属器结构异常或功能障碍的医学分支。", "boundary": "涵盖基底细胞癌、鳞状细胞癌、黑色素瘤等皮肤肿瘤，以及脱发、甲病、皮脂腺疾病等附属器病变。区分于感染引起的皮肤破坏（主挂感染性皮肤病）及全身性肿瘤的皮肤转移（主挂肿瘤学）。", "includes": ["皮肤良性与恶性肿瘤（如基底细胞癌、黑色素瘤）", "毛发、指甲及皮脂腺等非肿瘤性附属器疾病"], "excludes": ["由细菌、真菌或病毒直接感染引起的皮肤破坏", "全身性恶性肿瘤的皮肤转移灶"], "sibling_distinctions": [{"other_code": "N_98e828982a75a100", "rule": "感染性皮肤病侧重病原体直接感染；本节点侧重肿瘤性增生或附属器结构/功能异常。"}, {"other_code": "N_6a61da6711bb01df", "rule": "自身免疫与大疱性皮病侧重免疫介导的水疱或炎症；本节点侧重肿瘤或附属器形态学改变。"}], "cross_boundary_rule": "当皮肤肿瘤伴随明显炎症或免疫反应时，若以肿瘤组织学特征为主，主挂本节点；若以免疫介导的水疱或红斑为主，主挂自身免疫与大疱性皮病。"}, {"node_code": "N_6a61da6711bb01df", "definition": "研究由自身免疫机制介导的皮肤疾病，特别是以表皮或真皮-表皮连接处水疱形成为特征的皮病及其相关免疫病理。", "boundary": "涵盖天疱疮、类天疱疮、大疱性类天疱疮等自身免疫性大疱病，以及系统性红斑狼疮、皮肌炎等以皮肤为主要表现的自身免疫病。区分于单纯性过敏（主挂变态反应）及感染性水疱（主挂感染性皮肤病）。", "includes": ["自身免疫性大疱病（如天疱疮、类天疱疮）", "以皮肤为主要表现的自身免疫病（如盘状红斑狼疮、皮肌炎）"], "excludes": ["由过敏原直接引起的荨麻疹或接触性皮炎", "由细菌或病毒感染直接导致的水疱"], "sibling_distinctions": [{"other_code": "N_6d1d70a013db2aa7", "rule": "变态反应与炎症性皮肤病侧重I-IV型变态反应及非特异性炎症；本节点侧重自身抗体介导的免疫病理。"}, {"other_code": "N_98e828982a75a100", "rule": "感染性皮肤病侧重病原体感染；本节点侧重自身免疫系统攻击皮肤组织。"}], "cross_boundary_rule": "当疾病同时具有感染和自身免疫特征时，若自身抗体检测阳性且免疫病理支持自身免疫机制，主挂本节点；若病原体培养阳性且无自身抗体，主挂感染性皮肤病。"}]}
